import { useCallback, useState } from 'react';
import { Button, Drawer, Menu, MenuItem, MenuSeparator } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type SideNavProps = {
  onNavigate: (key: NavKey) => void;
};

const ITEMS: Array<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  return (
    <div className="jx-stack">
      <Button type="button" aria-expanded={open} onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer
        open={open}
        side="left"
        title="Навигация"
        onClose={() => setOpen(false)}
      >
        <Menu
          className="jx-stack"
          style={{ gap: 'var(--jx-space-1)', padding: 'var(--jx-space-2)' }}
        >
          {ITEMS.map((item) => (
            <MenuItem key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </MenuItem>
          ))}
          <MenuSeparator />
          <MenuItem tone="danger" onSelect={() => select('logout')}>
            Выйти
          </MenuItem>
        </Menu>
      </Drawer>
    </div>
  );
}

